    },
    "示例贴合": {
      "score": 4,
      "evidence": "以 192.168.1.130/26 为例：掩码 255.255.255.192 的二进制末字节为 `11000000`，与 IP 末字节 `10000010` 做按位与，得到 `10000000`，即网络地址 192.168.1.128",
      "reason": "示例采用具体IP和掩码进行二进制演算，与参考正文一致，且能帮助学生理解按位与运算。但缺少图文结合的视觉化呈现，对偏好图文结合的学生支持不足。"
    },
    "表达适配": {
      "score": 3,
      "evidence": "动手画地址块图。把一个 /24 按 /26、/27、/30 等不同掩码切分，标出每个子网的网络地址、广播地址和可用范围",
      "reason": "讲义提到画图练习，部分呼应学生图文结合的认知风格，但整体以文字和公式为主，没有实际提供图示或类比，对偏好类比和分步说明的学生支持不够充分。"
    },
    "目标可执行性": {
      "score": 4,
      "evidence": "先练二进制转换。掌握按位与运算。理解“借位”逻辑。动手画地址块图。用 VLSM 做规划练习",
      "reason": "学习步骤按从基础到应用的顺序排列，步骤明确且可操作，适合期末通过和先理解基础概念再做简单题的目标。但步骤数量较多，在每周3小时的限制下可能需要取舍。"
    },
    "事实准确性": {
      "score": 5,
      "evidence": "掩码必须是连续的 1 后跟连续的 0。255.255.255.192 合法，255.255.255.144 不合法",
      "reason": "掩码连续性、网络地址与广播地址不可分配、可用主机数公式等均与参考正文及通行网络知识一致。/31的补充说明也标注了RFC 3021来源，边界严谨。"
    }
  },
  "B": {
    "难度匹配": {
      "score": 4,
      "evidence": "想象一栋宿舍楼只有一个门牌号，快递员无法知道包裹该送到哪个房间。子网划分就是给每个“房间”分配独立的地址段",
      "reason": "以宿舍楼和快递员的类比引入，降低了初学者的理解门槛，符合大一学生基础薄弱、需要从直观概念起步的情况。学习步骤循序渐进，每周3小时可完成。"
    },
    "示例贴合": {
      "score": 4,
      "evidence": "IP：  192.168.1.130 → 11000000.10101000.00000001.10000010\n掩码：255.255.255.192 → 11111111.11111111.11111111.11000000\nAND： 192.168.1.128 → 11000000.10101000.00000001.10000000",
      "reason": "示例与参考正文一致，二进制演算过程完整展示，能帮助学生理解按位与运算。但示例仅有一个，缺少对不同掩码长度的对比示例，对简单题练习的支撑略有不足。"
    },
    "表达适配": {
      "score": 4,
      "evidence": "画图辅助理解：把子网想象成一段连续的地址区间，左端点是网络地址，右端点是广播地址，中间是可用主机",
      "reason": "开头的宿舍楼类比和复习建议中的画图方法贴合学生图文结合、类比和分步说明的认知偏好，表达方式较友好。但正文中实际图示仍然缺失，分步说明可以更细化。"
    },
    "目标可执行性": {
      "score": 4,
      "evidence": "第一步：先会做“与运算”。第二步：确定地址范围。第三步：练习 /26、/27、/30 等常见前缀。第四步：了解 VLSM",
      "reason": "步骤清晰且从基础到应用递进，每天一道小题的复习建议符合每周3小时的时间限制，能支撑期末通过和先理解基础概念的目标。"
    },
    "事实准确性": {
      "score": 5,
      "evidence": "可用主机数 = 2^h − 2，其中 h 是主机位数。减去的 2 就是网络地址和广播地址",
      "reason": "核心概念、公式和常见误区与参考正文及通行网络知识一致。/31的补充说明标注为补充内容并建议初学阶段先记住/30，边界处理严谨。"
    }
  }
}

